PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE players (
  uuid TEXT PRIMARY KEY,
  player_id TEXT NOT NULL,
  player_name TEXT NOT NULL,
  date_joined TEXT NOT NULL
, permission INT NOT NULL DEFAULT 0, score REAL NOT NULL DEFAULT 0, discord_avatar TEXT, discord_discriminator TEXT, account_status TEXT DEFAULT 'active', deactivated_at TEXT, deleted_at TEXT, legal_terms_accepted_at TEXT, legal_privacy_accepted_at TEXT, legal_version TEXT);
CREATE TABLE trials (
  name TEXT PRIMARY KEY
);
CREATE TABLE submissions (
  uuid TEXT PRIMARY KEY,

  player_uuid TEXT NOT NULL,
  trial_name TEXT NOT NULL,

  player_name TEXT NOT NULL,

  time REAL NOT NULL,
  date TEXT NOT NULL,

  state TEXT NOT NULL DEFAULT 'pending'
    CHECK (state IN ('approved', 'denied', 'pending')), "moderator_note" TEXT, thread_id TEXT DEFAULT NULL, moderator_username TEXT,

  FOREIGN KEY (player_uuid) REFERENCES players(uuid),
  FOREIGN KEY (trial_name) REFERENCES trials(name)
);
CREATE TABLE wrs (
  trial_name TEXT PRIMARY KEY,

  player_uuid TEXT NOT NULL,
  player_name TEXT NOT NULL,

  time REAL NOT NULL,
  date TEXT NOT NULL, submission_uuid TEXT NOT NULL REFERENCES submissions(uuid),

  FOREIGN KEY (player_uuid) REFERENCES players(uuid),
  FOREIGN KEY (trial_name) REFERENCES trials(name)
);
CREATE TABLE oauth_accounts (
  provider TEXT NOT NULL,
  provider_account_id TEXT NOT NULL,
  player_uuid TEXT NOT NULL,
  access_token TEXT,
  refresh_token TEXT,
  expires_at TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  PRIMARY KEY (provider, provider_account_id),
  FOREIGN KEY (player_uuid) REFERENCES players(uuid)
);
CREATE TABLE auth_sessions (
  token TEXT PRIMARY KEY,
  player_uuid TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  FOREIGN KEY (player_uuid) REFERENCES players(uuid)
);
CREATE TABLE pbs (
  player_uuid TEXT NOT NULL,
  trial_name TEXT NOT NULL,
  submission_uuid TEXT NOT NULL,
  player_name TEXT NOT NULL,
  time REAL NOT NULL,
  date TEXT NOT NULL,
  PRIMARY KEY (player_uuid, trial_name),
  FOREIGN KEY (player_uuid) REFERENCES players(uuid),
  FOREIGN KEY (submission_uuid) REFERENCES submissions(uuid),
  FOREIGN KEY (trial_name) REFERENCES trials(name)
);
CREATE TABLE audit_logs (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  actor_uuid TEXT,
  actor_name TEXT,
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_uuid TEXT,
  target_type TEXT,
  target_uuid TEXT,
  details TEXT,
  FOREIGN KEY (actor_uuid) REFERENCES players(uuid)
);
CREATE TABLE api_idempotency_keys (
  scope TEXT NOT NULL,
  idempotency_key TEXT NOT NULL,
  actor_uuid TEXT NOT NULL,
  request_hash TEXT NOT NULL,
  response_json TEXT NOT NULL,
  status_code INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  PRIMARY KEY (scope, idempotency_key, actor_uuid)
);
CREATE TABLE api_rate_limits (
  bucket_key TEXT PRIMARY KEY,
  count INTEGER NOT NULL,
  window_start INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
);
CREATE TABLE player_ips (
  player_uuid TEXT NOT NULL,
  ip_address TEXT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  first_seen TEXT NOT NULL,
  last_seen TEXT NOT NULL,
  PRIMARY KEY (player_uuid, ip_address),
  FOREIGN KEY (player_uuid) REFERENCES players(uuid)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_audit_logs_created_at ON audit_logs(created_at);
CREATE INDEX idx_oauth_accounts_provider_account ON oauth_accounts(provider, provider_account_id);
CREATE INDEX idx_auth_sessions_expiry ON auth_sessions(expires_at);
CREATE INDEX idx_players_score_name ON players(score DESC, player_name ASC);
CREATE INDEX idx_wrs_trial_name ON wrs(trial_name);
CREATE INDEX idx_pbs_player_uuid ON pbs(player_uuid);
CREATE INDEX idx_pbs_trial_name ON pbs(trial_name);
CREATE INDEX idx_submissions_uuid_state ON submissions(uuid, state);
CREATE INDEX idx_submissions_trial_state_time_date ON submissions(trial_name, state, time, date);
CREATE INDEX idx_submissions_player_date ON submissions(player_uuid, date DESC);
CREATE INDEX idx_submissions_state_trial_date ON submissions(state, trial_name, date DESC);
CREATE INDEX idx_submissions_player_trial_state ON submissions(player_uuid, trial_name, state);
CREATE INDEX idx_audit_logs_action_created_at ON audit_logs(action, created_at);
CREATE INDEX idx_oauth_accounts_provider_player ON oauth_accounts(provider, provider_account_id, player_uuid);
CREATE INDEX idx_auth_sessions_player_uuid ON auth_sessions(player_uuid);
CREATE INDEX idx_auth_sessions_token_expires ON auth_sessions(token, expires_at);
CREATE INDEX idx_pbs_player_trial ON pbs(player_uuid, trial_name);
CREATE INDEX idx_submissions_trial_name ON submissions(trial_name);
CREATE INDEX idx_submissions_date ON submissions(date);
CREATE INDEX idx_submissions_state_trial_time_date ON submissions(state, trial_name, time, date);
CREATE INDEX idx_submissions_player_state_trial_date ON submissions(player_uuid, state, trial_name, date);
CREATE INDEX idx_api_rate_limits_window_start ON api_rate_limits(window_start);
CREATE INDEX idx_api_idempotency_expires ON api_idempotency_keys(expires_at);
CREATE INDEX idx_player_ips_player_uuid ON player_ips(player_uuid);
CREATE INDEX idx_player_ips_ip_address ON player_ips(ip_address);
